-- 094: 院级项目申报批次、资格/限额规则和评审计划配置。
-- 只保存规则和计划，不伪造专家或评审结果；申请提交时由服务端重新核验规则。
BEGIN;

CREATE TABLE IF NOT EXISTS "院级项目申报批次" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "计划年度" integer NOT NULL,
    "批次名称" varchar(200) NOT NULL,
    "项目类别" varchar(80) NOT NULL DEFAULT '院级科研项目',
    "发布开始日期" date NOT NULL,
    "截止日期" date NOT NULL,
    "个人申报限额" integer NOT NULL DEFAULT 3,
    "批次总限额" integer,
    "资格规则" jsonb NOT NULL DEFAULT '{}'::jsonb,
    "评审方案" jsonb NOT NULL DEFAULT '{}'::jsonb,
    "评审开始日期" date,
    "评审截止日期" date,
    "状态" varchar(10) NOT NULL DEFAULT '草稿',
    "批次说明" varchar(2000),
    "创建人编号" integer REFERENCES "人员"("编号"),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ck_院级项目申报批次_年度" CHECK ("计划年度" BETWEEN 2000 AND 2200),
    CONSTRAINT "ck_院级项目申报批次_日期" CHECK ("截止日期" >= "发布开始日期"),
    CONSTRAINT "ck_院级项目申报批次_评审日期" CHECK ("评审截止日期" IS NULL OR "评审开始日期" IS NULL OR "评审截止日期" >= "评审开始日期"),
    CONSTRAINT "ck_院级项目申报批次_个人限额" CHECK ("个人申报限额" > 0),
    CONSTRAINT "ck_院级项目申报批次_总限额" CHECK ("批次总限额" IS NULL OR "批次总限额" > 0),
    CONSTRAINT "ck_院级项目申报批次_状态" CHECK ("状态" IN ('草稿','发布','关闭')),
    CONSTRAINT "uq_院级项目申报批次_名称" UNIQUE ("计划年度", "批次名称")
);

CREATE INDEX IF NOT EXISTS "ix_院级项目申报批次_状态日期"
    ON "院级项目申报批次" ("状态", "发布开始日期", "截止日期");

ALTER TABLE "纵向项目申报"
    ADD COLUMN IF NOT EXISTS "院级批次编号" bigint;

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_纵向项目申报_院级批次') THEN
        ALTER TABLE "纵向项目申报"
            ADD CONSTRAINT "fk_纵向项目申报_院级批次"
            FOREIGN KEY ("院级批次编号") REFERENCES "院级项目申报批次"("编号") ON DELETE SET NULL;
    END IF;
END $$;

CREATE INDEX IF NOT EXISTS "ix_纵向项目申报_院级批次"
    ON "纵向项目申报" ("院级批次编号", "申报人编号", "申报年度");

-- 让现有申报流程保存院级批次编号；不改变原有纵向字段和参与人同步逻辑。
CREATE OR REPLACE FUNCTION "sp_纵向项目申报_增改"(p_payload jsonb)
RETURNS integer LANGUAGE plpgsql AS $$
DECLARE
    r record;
    v_new_id integer;
    v_template_id integer := COALESCE((p_payload->>'流程模板编号')::integer, 400);
    v_tt jsonb;
BEGIN
    v_tt := CASE WHEN p_payload ? 'tt' AND jsonb_typeof(p_payload->'tt') = 'array'
                 THEN p_payload->'tt' ELSE "pg_first_json_array"(p_payload) END;
    FOR r IN SELECT * FROM jsonb_to_recordset(v_tt) AS x(
        "编号" integer, "分类" integer, "项目名称" varchar(100), "申报人编号" integer,
        "学科门类" varchar(50), "学科类型" varchar(50), "申报年度" integer, "申报计划编号" bigint,
        "院级批次编号" bigint, "项目类型" varchar(50), "项目级别" varchar(50), "项目来源单位" varchar(50),
        "项目类别" varchar(50), "申报时间" timestamp without time zone, "申请经费" numeric(18,2),
        "计划开始日期" date, "计划完成日期" date, "项目等级" varchar(50),
        "是否委托外单位进行实验或实验分析" boolean, "实验委托检测内容" varchar(1000),
        "项目摘要" varchar(1000), "是否需要伦理评审" boolean, "是否需要伦理批文" boolean,
        "伦理批文编号" varchar(50), "伦理批文路径" text, "项目申报书路径" text,
        "备注" varchar(500), "建立时间" timestamp without time zone, "是否立项" boolean
    ) LOOP
        IF COALESCE(r."编号",0)=0 THEN
            INSERT INTO "纵向项目申报" (
              "编号","分类","项目名称","申报人编号","学科门类","学科类型","申报年度","申报计划编号","院级批次编号",
              "项目类型","项目级别","项目来源单位","项目类别","申报时间","申请经费","计划开始日期","计划完成日期","项目等级",
              "是否委托外单位进行实验或实验分析","实验委托检测内容","项目摘要","是否需要伦理评审","是否需要伦理批文",
              "伦理批文编号","伦理批文路径","项目申报书路径","备注","建立时间","是否立项")
            VALUES (nextval(pg_get_serial_sequence('"纵向项目申报"','编号')),COALESCE(r."分类",1),r."项目名称",r."申报人编号",r."学科门类",r."学科类型",
              COALESCE(r."申报年度",EXTRACT(YEAR FROM CURRENT_DATE)::integer),r."申报计划编号",r."院级批次编号",r."项目类型",r."项目级别",r."项目来源单位",r."项目类别",
              COALESCE(r."申报时间",CURRENT_TIMESTAMP),COALESCE(r."申请经费",0),r."计划开始日期",r."计划完成日期",r."项目等级",r."是否委托外单位进行实验或实验分析",
              r."实验委托检测内容",r."项目摘要",r."是否需要伦理评审",r."是否需要伦理批文",r."伦理批文编号",r."伦理批文路径",r."项目申报书路径",r."备注",CURRENT_TIMESTAMP,r."是否立项")
            RETURNING "编号" INTO v_new_id;
        ELSE
            UPDATE "纵向项目申报" SET
              "分类"=COALESCE(r."分类","分类"),"项目名称"=COALESCE(r."项目名称","项目名称"),"申报人编号"=COALESCE(r."申报人编号","申报人编号"),
              "学科门类"=r."学科门类","学科类型"=r."学科类型","申报年度"=COALESCE(r."申报年度","申报年度"),
              "申报计划编号"=r."申报计划编号","院级批次编号"=r."院级批次编号","项目类型"=r."项目类型","项目级别"=r."项目级别",
              "项目来源单位"=r."项目来源单位","项目类别"=r."项目类别","申报时间"=COALESCE(r."申报时间","申报时间"),"申请经费"=COALESCE(r."申请经费","申请经费"),
              "计划开始日期"=COALESCE(r."计划开始日期","计划开始日期"),"计划完成日期"=COALESCE(r."计划完成日期","计划完成日期"),"项目等级"=r."项目等级",
              "是否委托外单位进行实验或实验分析"=r."是否委托外单位进行实验或实验分析","实验委托检测内容"=r."实验委托检测内容","项目摘要"=r."项目摘要",
              "是否需要伦理评审"=r."是否需要伦理评审","是否需要伦理批文"=r."是否需要伦理批文","伦理批文编号"=r."伦理批文编号","伦理批文路径"=r."伦理批文路径",
              "项目申报书路径"=r."项目申报书路径","备注"=r."备注","是否立项"=r."是否立项"
            WHERE "编号"=r."编号";
            v_new_id:=r."编号";
        END IF;
    END LOOP;
    IF v_new_id IS NOT NULL AND p_payload ? 'tt_项目参与人' AND jsonb_typeof(p_payload->'tt_项目参与人')='array' THEN
      DELETE FROM "项目参与人" WHERE "流程模板编号"=v_template_id AND "项目编号"=v_new_id;
      INSERT INTO "项目参与人" ("流程模板编号","项目编号","参与人编号","工作量占比","备注","建立时间")
      SELECT v_template_id,v_new_id,p."参与人编号",p."工作量占比",p."备注",CURRENT_TIMESTAMP
      FROM jsonb_to_recordset(p_payload->'tt_项目参与人') AS p("参与人编号" integer,"工作量占比" integer,"备注" varchar(500))
      WHERE p."参与人编号" IS NOT NULL AND p."参与人编号">0;
    END IF;
    RETURN COALESCE(v_new_id,0);
END;
$$;

INSERT INTO "权限" ("编号", "上级编号", "名称", "路径", "类型", "备注")
VALUES (206, 2, '院级项目批次', '科研办公/科研办公/院级项目批次.html', TRUE, '维护院级项目申报批次、资格限额和评审方案')
ON CONFLICT ("编号") DO UPDATE
SET "上级编号"=EXCLUDED."上级编号", "名称"=EXCLUDED."名称", "路径"=EXCLUDED."路径", "类型"=EXCLUDED."类型", "备注"=EXCLUDED."备注";

INSERT INTO "角色权限" ("角色编号", "权限编号")
SELECT r."编号", 206 FROM "角色" r
 WHERE r."名称" IN ('系统管理员','科研管理员','科技办')
   AND NOT EXISTS (SELECT 1 FROM "角色权限" rp WHERE rp."角色编号"=r."编号" AND rp."权限编号"=206);

UPDATE "系统迁移版本"
   SET "版本"=94, "脚本"='094_internal_project_batches.sql',
       "检查摘要"='增加院级项目批次、申报限额/资格规则和评审方案配置', "应用时间"=CURRENT_TIMESTAMP
 WHERE "编号"=1;

COMMIT;
